check('all98 CSVscores matchaudited arrays',len(rows)==98 and all(abs(float(r['wape'])-s['wape'])<1e-11 and abs(float(r['daily_wape'])-s['daily_wape'])<1e-11 and abs(float(r['peak_mape'])-s['peak_mape'])<1e-11 for r,s in zip(rows,a['rows'])));check('topaliases current',sha(T/'9月28日指标完整模型对照.csv')==sha(T/'模型各项指标完整结果.csv') and sha(T/'9月28日指标预测区间对照.csv')==sha(T/'模型预测区间结果.csv'))
entries=read(B/'round36/results/current_entry_verification.json')['entries']
for r in entries:
 H=r['horizon_days'];check(f'H{H} currentfileSHA',sha(r['curve'])==r['curve_sha256'] and sha(r['daily'])==r['daily_sha256'])
 with Path(r['curve']).open(encoding='utf-8-sig') as f:rr=list(csv.DictReader(f))
 vals=np.array([float(x['forecast_normalized_power']) for x in rr]);lower=np.array([float(x['lower80_empirical']) for x in rr]);upper=np.array([float(x['upper80_empirical']) for x in rr]);check(f'H{H} 57PDU points finiteboundedorderedintervals',len(rr)==57*H*96 and len({x['pdu'] for x in rr})==57 and np.isfinite(vals).all() and vals.min()>=0 and vals.max()<=1 and np.isfinite(lower).all() and np.isfinite(upper).all() and lower.min()>=0 and upper.max()<=1 and np.all(lower<=upper));check(f'H{H} datesandhistoricalflags',min(x['timestamp_local_PT'] for x in rr)=='2019-06-01T00:00' and max(x['timestamp_local_PT'] for x in rr)==f'2019-06-{H:02d}T23:45' and all(x['historical_replay']=='True' for x in rr))
 with Path(r['daily']).open(encoding='utf-8-sig') as f:dd=list(csv.DictReader(f))
 av=np.array([float(x['daily_mean_normalized_power']) for x in dd]);check(f'H{H} dailyexactfrom96samepoints',len(dd)==57*H and np.max(abs(av-vals.reshape(57*H,96).mean(-1)))<1e-12);check(f'H{H} currententryupdated',"round36\\code\\read_current_moirai.py" in (T/f'19_{H}天当前推荐模型历史复现.cmd').read_text(encoding='utf-8'))
for nr in [34,35,36]:check(f'R{nr} pipelinecompleted',read(B/f'round{nr}/results/resource_status.json')['stage']=='completed')
